import openpyxl

for variant in ['a', 'b', 'c']:
    fname = f'data/workbooks/working_paper_variant_{variant}.xlsx'
    wb = openpyxl.load_workbook(fname, data_only=True)
    print(f'\n=== Variant {variant} ===')
    for sn in ['lap-1', 'lap-2', 'lap-9']:
        ws = wb[sn]
        # Find all Calculate rows
        calcs = []
        for row in ws.iter_rows(min_row=1, max_row=ws.max_row, max_col=1, values_only=False):
            v = row[0].value
            if v and str(v).startswith('Calculate'):
                calcs.append((row[0].row, v))
        print(f'{sn}: {len(calcs)} blocks, Calculate rows: {calcs[:3]}...{calcs[-3:]}')
        # Print last block's rows
        if calcs:
            last_start = calcs[-1][0]
            print(f'  Last block starts at row {last_start}:')
            for r in range(last_start, min(last_start+25, ws.max_row+1)):
                vals = []
                for c in range(1, 6):
                    vals.append(ws.cell(row=r, column=c).value)
                print(f'    Row {r}: {vals}')
